import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.close();

        System.out.println(n * m - compute(n, m));
    }

    public static int compute(int n, int m) {
        if (n < m) {
            int temp = n;
            n = m;
            m = temp;
        }
        if (m == 1) {
            Map<Integer, Integer> pattern = new HashMap<>();
            pattern.put(0, 0);
            pattern.put(1, 1);
            pattern.put(2, 2);
            pattern.put(3, 3);
            pattern.put(4, 2);
            pattern.put(5, 1);
            return pattern.get(n % 6);
        }
        if (n == 7) {
            if (m == 2) {
                return 2;
            }
            return (n * m) % 2;
        } else if (n >= 4) {
            return (n * m) % 2;
        } else {
            Map<String, Integer> pairs = new HashMap<>();
            pairs.put("3,2", 2);
            pairs.put("3,1", 3);
            pairs.put("2,2", 4);
            pairs.put("2,1", 2);
            String key = n + "," + m;
            return pairs.getOrDefault(key, (n * m) % 2);
        }
    }
}
